#!/usr/bin/env python3
"""Attach the audited new cohorts without altering historical measurement inputs."""
import argparse,base64,copy,hashlib,html,json,pathlib,re,shutil
import tailcache12_service_verify as checks

ROOT=pathlib.Path(__file__).resolve().parents[1]
BASE=ROOT/'docs/service-followup'
START='<!-- TAILCACHE_SERVICE_START -->';END='<!-- TAILCACHE_SERVICE_END -->'


def render_component(hosted=False):
    path=BASE/'followup-data-20261117.json';raw=path.read_text();data=json.loads(raw);checks.verify(data)
    digest=hashlib.sha256(path.read_bytes()).hexdigest()
    if hosted:
        summary=copy.deepcopy(data);summary['curves'].pop('data');raw=json.dumps(summary,separators=(',',':'))
    if '</script' in raw.lower():raise ValueError('Unsafe embedded data terminator')
    esc=html.escape;url='service-data.json' if hosted else ''
    css='''<style>#service-followup{background:#fff;color:#173048;border:1px solid #b7c9da;border-radius:10px;padding:25px;margin:24px 0;font:15px/1.55 system-ui,sans-serif;overflow-wrap:anywhere}#service-followup *{box-sizing:border-box}#service-followup h2{font-size:28px;line-height:1.2;margin:8px 0 14px}#service-followup h3{font-size:19px;margin:22px 0 10px}#service-followup p{margin:8px 0}#service-followup a{color:#075f8e}#service-followup .sf-muted{font-size:13px;color:#486078}#service-followup .sf-cards,#service-followup .sf-facts{display:grid;grid-template-columns:repeat(3,minmax(0,1fr));gap:15px;margin:18px 0}#service-followup .sf-facts{grid-template-columns:repeat(2,minmax(0,1fr))}#service-followup .sf-cards>div,#service-followup .sf-facts>div{border:1px solid #d5e0e9;padding:15px;background:#f5f9fc;border-radius:7px}#service-followup .sf-controls{display:flex;flex-wrap:wrap;gap:12px;margin:20px 0}#service-followup label{display:flex;flex-direction:column;font-size:13px;gap:5px;min-width:150px}#service-followup select,#service-followup button,#service-followup .sf-link{font:inherit;color:#173048;background:white;border:1px solid #9eb5c7;border-radius:5px;padding:9px 12px;min-height:42px}#service-followup button{cursor:pointer;width:auto}#service-followup .sf-shortcuts{display:flex;gap:9px;flex-wrap:wrap}#service-followup button:hover{background:#edf6fb}#service-followup :focus-visible{outline:3px solid #087ca7;outline-offset:3px}#service-followup .sf-scroll{overflow-x:auto;max-width:100%}#service-followup svg{display:block;width:100%;font-family:system-ui,sans-serif;color:#173048}#service-followup table{border-collapse:collapse;width:100%;min-width:710px;font-size:13px}#service-followup td,#service-followup th{border-bottom:1px solid #dce4eb;padding:10px;text-align:left;vertical-align:top}#service-followup th{background:#f3f7fa}#service-followup td button,#service-followup th button{font-size:13px;text-align:left;border:0;background:transparent;padding:0;color:#075f8e}#service-followup summary{font-weight:650;cursor:pointer;padding:13px 0}#service-followup .sf-note{border-left:4px solid #0d7395;background:#eef7fb;padding:12px 16px}#service-followup figure{margin:20px 0;padding:12px;border:1px solid #d5e0e9;border-radius:7px}#service-followup figure img{width:100%;height:auto;display:block}#service-followup figcaption{font-size:13px;color:#486078;margin-top:9px}#service-followup .sf-glossary dt{font-weight:650;margin-top:12px}#service-followup .sf-glossary dd{margin:4px 0 10px}#service-followup .sf-links{display:flex;flex-wrap:wrap;gap:10px;margin:16px 0}@media(max-width:760px){#service-followup{padding:15px}#service-followup h2{font-size:24px}#service-followup .sf-cards,#service-followup .sf-facts{grid-template-columns:1fr}#service-followup label{min-width:125px;max-width:100%;flex:1}#service-followup select{max-width:100%}}</style>'''
    parts=[START,css,f'<section id="service-followup" data-package-url="{url}" data-package-sha="{digest}" aria-labelledby="sf-title">',
    '''<p class="sf-muted">Research follow-up · 17 November 2026 · 184 research JVMs · 30 controls · eight separate cohorts</p><h2 id="sf-title">Why the tail-latency answer changes</h2><p>The completed experiments support a conditional story about policy, logical traces and latency definitions. They do not establish a general pressure-induced ordinary-service crossover.</p><div class="sf-cards"><div><strong>Service: no general forward crossover</strong><p>The 8 KiB screen did not improve Chronicle’s p99.9 ranking with pressure. Its worth rule stopped after four forks.</p></div><div><strong>Policy changes the small-value result</strong><p>At 512 B, Chronicle beats bounded Caffeine in the custom recorder; unbounded Caffeine reverses that ordering. The contracts differ.</p></div><div><strong>Trace pattern changes baseline response</strong><p>With equal trace-array sizes, repeated-short favors Caffeine and uniform-long favors Chronicle. Raw array geometry alone is insufficient.</p></div></div><p class="sf-note"><strong>Keep the evidence boundaries.</strong> JMH does not reproduce a general small/intermediate-payload service advantage. Every warning and contrary fork remains visible. The original unconditional Task 12 protocol remains NO_GO. This is an agent-reviewed working draft, with human review and public release still pending.</p><div class="sf-shortcuts"><button type="button" data-cohort="geometry">Inspect trace control</button><button type="button" data-cohort="policy">Inspect cache policy</button><button type="button" data-cohort="replication">Inspect service replication</button><button type="button" data-cohort="observer">Inspect JMH sensitivity</button></div><div id="sf-chart-anchor"></div><div class="sf-controls"><label>Experiment<select id="sf-cohort"></select></label><label>Evidence stage<select id="sf-stage"></select></label><label>Latency channel<select id="sf-metric"></select></label><label>Percentile<select id="sf-q"><option>99</option><option selected>99.9</option><option>99.99</option><option>99.999</option></select></label></div><p id="sf-scope" class="sf-muted" aria-live="polite"></p><div id="sf-ratio" class="sf-scroll"></div><p class="sf-muted">Below 1: Chronicle lower. Above 1: the named Caffeine configuration lower. Dots are paired forks; horizontal offsets separate repeats. Scroll the chart/table horizontally on narrow screens. A direction is descriptive, not significance or a precise crossover.</p><div id="sf-table" class="sf-scroll"></div><h3 id="sf-detail-title">Selected point</h3><label>Retained pair<select id="sf-block"></select></label><div id="sf-detail"></div><button id="sf-load-tail" type="button">Load full tail and stall rates</button><div id="sf-tail" class="sf-scroll"><p class="sf-muted">Choose a point or dot, then load its separate per-fork survival curves.</p></div><div id="sf-rates" class="sf-scroll"></div><p id="sf-tail-note" class="sf-muted"></p><details><summary>Conclusions at all 58 comparison groups</summary><p>Each row keeps its own declared primary channel. Changing the percentile updates the rows; a diagnostic view does not replace the frozen primary endpoint. The groups are not one combined ranking.</p><div id="sf-all-table" class="sf-scroll"></div></details><details><summary>What the terms mean</summary><dl class="sf-glossary"><dt>Ballast</dt><dd>Strongly retained application byte-array payload independent of the cache. Labels exclude object/reference overhead. Zero ballast still includes the cache, trace and JVM.</dd><dt>Churn</dt><dd>Common background allocation demand, offered at 32 MiB/s with a bounded retention ring. Actual allocated and dropped demand are recorded; a stall can reduce delivery.</dd><dt>Service / saturated service</dt><dd>Service is completion minus actual operation start, including fresh-value generation on updates. Saturated runs execute back to back. Service inside a paced run is a different workload regime.</dd><dt>Scheduled response and queue debt</dt><dd>Response is completion minus intended arrival at 50,000 requests/s. Overdue requests are retained and processed serially, so a pause delays later requests too. This is an in-process schedule.</dd><dt>p99.9, p99.99 and p99.999</dt><dd>Upper tail fractions are 0.1%, 0.01% and 0.001%. A 1.5-million-response fork has about 15 nominal observations beyond p99.999; those can share a pause. Sparse JMH samples may support only a few extreme observations.</dd><dt>GC wall-time share versus affected calls</dt><dd>One long pause can consume much of a window while affecting few operations. In one high-pressure fork, GC takes 39.36% wall time but spans only 0.0010944% of service calls. These denominators explain why p99.9 can look small while p99.999 is large.</dd><dt>Trace / equal-array control</dt><dd>The trace predefines keys and read/update order. Both control patterns use 1,000,003 long keys and boolean flags; updated keys differ (1,939 versus 25,532). Ordering, active keys and lifetime still change together.</dd><dt>Bounded / direct / unbounded Caffeine</dt><dd>Bounded Caffeine tracks a size policy with headroom for these fixed residents. Direct execution runs maintenance on the calling thread; default uses the common pool. Unbounded removes the automatic size limit and changes policy/layout. No eviction workload is measured.</dd><dt>JIT, floor and warnings</dt><dd>JIT is JVM runtime compilation/optimization. Fixed warmup does not prove steady state. Timer, injected-pause and fresh-supply floors test accounting/observability; their time is not subtracted. Warning-free means no recorded warning, not proof of a neutral recorder.</dd><dt>Heap, RSS and tiering</dt><dd>Heap is GC-managed memory. RSS is sampled process residency, including native map pages. Lower heap retention can coexist with higher RSS. Chronicle’s configured segment-tier growth policy is logged; these comparisons use in-memory maps with analytics disabled.</dd></dl></details><details><summary>Seven scientific figures and their limits</summary>''']
    index=json.loads((BASE/'figure-index-20261117.json').read_text())
    manifest=json.loads((BASE/'render-manifest-20261117.json').read_text())
    for i,f in enumerate(index,1):
        file=BASE/'figures'/(f['id']+'.png')
        if hashlib.sha256(file.read_bytes()).hexdigest()!=manifest['outputs']['figures/'+file.name]:
            raise ValueError('Scientific figure does not match render manifest')
        src='service-figures/'+file.name if hosted else 'data:image/png;base64,'+base64.b64encode(file.read_bytes()).decode()
        parts.append(f'<figure><img loading="lazy" src="{src}" alt="{esc(f["title"])}"><figcaption><strong>Figure A{i}.</strong> {esc(f["caption"])}</figcaption></figure>')
    parts.append('''</details><div class="sf-links"><a id="sf-download" class="sf-link" href="'''+(url or '#')+'''" download="tailcache-followup-20261117.json">Download verified follow-up data</a><a class="sf-link" href="https://github.com/Enixes/TailCache/blob/codex/tailcache-preprint/docs/service-followup/RESULTS_20261117.md">Research conclusions and limits</a><a class="sf-link" href="https://github.com/Enixes/TailCache/pull/10">Review manuscript PR #10</a></div><p class="sf-muted">184 raw-integrity-checked research forks, 704 nonempty exported distributions, 3,520 portable percentile checks and 58 point groups. Two/three-pair ranges remain descriptive; discovery cells can have only one pair. JMH uses eight one-second measurement iterations; the common controller’s unused generic 30-second field is clarified in the retained notes. Historical cohorts below retain their original scope and fingerprints.</p></section>''')
    downloads=[]
    for name,label in [('RESULTS_20261117.md','Download results'),('FINAL_REVIEW_20261117.md','Download technical review'),('CLAIMS_20261117.md','Download follow-up claims')]:
        content=(BASE/name).read_bytes()
        downloads.append(f'<a class="sf-link" href="data:text/markdown;base64,{base64.b64encode(content).decode()}" download="{name}" data-sha256="{hashlib.sha256(content).hexdigest()}">{label}</a>')
    parts[-1]=parts[-1].replace('</section>','<div class="sf-links">'+''.join(downloads)+'</div></section>')
    parts += ['<script id="sf-data" type="application/json">'+raw+'</script>','<script>'+(ROOT/'scripts/tailcache12_service_ui.js').read_text()+'</script>',END]
    return ''.join(parts)


def attach(page,component=None):
    page=re.sub(re.escape(START)+'.*?'+re.escape(END),'',page,flags=re.S)
    component=render_component() if component is None else component
    marker='<main class="wrap">'
    if marker in page:return page.replace(marker,marker+component,1)
    return re.sub(r'(<body[^>]*>)',lambda m:m[0]+component,page,count=1)


def main():
    parser=argparse.ArgumentParser(description=__doc__);parser.add_argument('--site-out',type=pathlib.Path);args=parser.parse_args()
    path=ROOT/'docs/TAILCACHE_RESULTS_EXPLORER.html';base=path.read_text();page=attach(base);path.write_text(page)
    midpoint=ROOT/'docs/TAILCACHE_MIDPOINT_EXPLORER.html'
    if midpoint.exists():midpoint.write_text(attach(midpoint.read_text()))
    if args.site_out:
        args.site_out.mkdir(parents=True,exist_ok=True)
        (args.site_out/'index.html').write_text(attach(base,render_component(hosted=True)))
        shutil.copyfile(BASE/'followup-data-20261117.json',args.site_out/'service-data.json')
        shutil.copyfile(ROOT/'docs/interactive/vercel.json',args.site_out/'vercel.json')
        shutil.copytree(BASE/'figures',args.site_out/'service-figures',dirs_exist_ok=True)
    print(json.dumps(dict(htmlBytes=path.stat().st_size,site=str(args.site_out),dataSha256=hashlib.sha256((BASE/'followup-data-20261117.json').read_bytes()).hexdigest())))


if __name__=='__main__':main()
